mapper.select:
SELECT a.id, a.stock_id, sum(num) as num, sum(price) as price, b.add_date, b.store_id, b.HANDLER, b.STATUS, b.supplier, b.depository_numbers, b.process_instance_id FROM consumable_stock_detail a INNER JOIN consumable_add_record b ON a.stock_id = b.id inner join consumable c on a.consumable_id=c.id
b.add_date = #{param.addDate}
and b.add_date = #{param.status}
and b.store_id = #{param.storeId}
and (c.name like concat('%',#{param.keyword},'%') or b.depository_numbers concat('%',#{param.keyword},'%'))
GROUP BY b.id order by b.create_time desc

SELECT SUM(num) AS valus
FROM consumable_reduce_record a
         INNER JOIN consumable_stock_detail b ON a.id = b.stock_id
WHERE a.status = 'PASS'
  AND reduce_date BETWEEN #{date.startTime}
    AND #{date.endTime}
